import { useEffect, useState } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { useNavigate } from 'react-router-dom';
import { getLampadas, addLampada, toggleLampada, deleteLampada } from '../utils/lampadaApi';
import LampadaCard from './DeviceCard';
import AddLampadaForm from './AddLampadaForm';

export default function Dashboard() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const [lampadas, setLampadas] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    getLampadas().then(data => {
      setLampadas(data);
      setLoading(false);
    });
  }, []);

  const handleAdd = async (nome) => {
    const nova = await addLampada(nome);
    setLampadas(prev => [...prev, nova]);
  };

  const handleToggle = async (id) => {
    const atualizada = await toggleLampada(id);
    setLampadas(prev => prev.map(l => l.id === id ? atualizada : l));
  };

  const handleDelete = async (id) => {
    await deleteLampada(id);
    setLampadas(prev => prev.filter(l => l.id !== id));
  };

  const handleLogout = () => {
    logout();
    navigate('/');
  };

  if (loading) return <div className="text-center p-8">Carregando dispositivos...</div>;

  return (
    <div className="min-h-screen bg-gray-100 p-6">
      <div className="max-w-4xl mx-auto">
        <div className="flex justify-between items-center mb-6">
          <h1 className="text-3xl font-bold text-gray-800">Minhas Lâmpadas Inteligentes</h1>
          <div className="flex items-center gap-4">
            <span className="text-gray-600">Olá, {user?.email}</span>
            <button
              onClick={handleLogout}
              className="bg-red-500 hover:bg-red-600 text-white px-4 py-2 rounded-lg"
            >
              Sair
            </button>
          </div>
        </div>

        <AddLampadaForm onAdd={handleAdd} />

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-6">
          {lampadas.map(lamp => (
            <LampadaCard
              key={lamp.id}
              lampada={lamp}
              onToggle={handleToggle}
              onDelete={handleDelete}
            />
          ))}
        </div>

        {lampadas.length === 0 && (
          <p className="text-center text-gray-500 mt-8">Nenhuma lâmpada cadastrada. Adicione a primeira!</p>
        )}
      </div>
    </div>
  );
}
